"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["34694"],{80468(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.guarda_da_vaga_nao_declaravel","status":422,"titulo":"A guarda da vaga declarada n\xe3o \xe9 uma das op\xe7\xf5es aceitas"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.guarda_da_vaga_nao_declaravel","requisitos":["UNI-REQ-0348"],"oQueAconteceu":["A configura\xe7\xe3o do recurso de uma etapa declara uma **guarda da vaga** que n\xe3o \xe9 uma das op\xe7\xf5es aceitas (UNI-REQ-0348). A guarda da vaga diz se a vaga em disputa fica guardada at\xe9 o resultado definitivo enquanto o recurso \xe9 julgado. A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `etapas[i].recursos[j].guardaDaVaga`, em que `i` \xe9 a posi\xe7\xe3o da etapa e `j`, a do recurso na etapa.","A mensagem da resposta diz: \\"A guarda da vaga n\xe3o \xe9 uma das op\xe7\xf5es aceitas: guardar a vaga at\xe9 o resultado definitivo ou n\xe3o guardar a vaga. Sem a guarda informada, vale guardar at\xe9 o resultado definitivo.\\" Ela n\xe3o repete o valor enviado."],"comoResolver":["Informe, em `guardaDaVaga`, um destes c\xf3digos: `ATE_O_RESULTADO_DEFINITIVO` (a vaga fica guardada at\xe9 o resultado definitivo) ou `NAO_GUARDA` (a vaga n\xe3o fica guardada durante o recurso). Se o campo ficar em branco, vale `ATE_O_RESULTADO_DEFINITIVO`. Com inst\xe2ncia superior, s\xf3 `ATE_O_RESULTADO_DEFINITIVO` \xe9 aceito; veja [guarda com inst\xe2ncia superior](/erros/uniplus.selecao.configuracao_do_recurso_da_etapa.nao_guarda_com_instancia_superior)."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);